package probe;import java.nio.ByteBuffer;public class Main{public static void main(String[] args){Throwable source=new BufferOverflowException();Throwable foreign=new foreign.BufferOverflowException();System.out.println((source instanceof BufferOverflowException)+":"+(source instanceof java.nio.BufferOverflowException)+":"+(foreign instanceof foreign.BufferOverflowException)+":"+(foreign instanceof java.nio.BufferOverflowException));System.out.println(RuntimeException.class.isAssignableFrom(source.getClass())+":"+RuntimeException.class.isAssignableFrom(foreign.getClass()));try{ByteBuffer.allocate(0).put((byte)1);}catch(Exception e){System.out.println((e instanceof java.nio.BufferOverflowException)+":"+(e instanceof BufferOverflowException)+":"+(e instanceof RuntimeException)+":"+(e.getClass()==java.nio.BufferOverflowException.class));}}}
